// Turns tokens.json plus mobile.json into the files the phone apps read. Run from anywhere:
//   node design/tokens/build-mobile.mjs
//   --check   write nothing; exit 1 if a generated file is out of date or a mobile rule fails (for CI)
// No dependencies. Outputs:
//   apps/mobile/ios/Whimbrel/DesignSystem/Tokens.generated.swift
//   apps/mobile/android/app/src/main/java/com/mpointer/whimbrel/mobile/design/Tokens.generated.kt
//
// Colors: only the fixed colors are generated. The 15 skinnable colors keep coming through each app's
// theme loader (themes/*.json), so components follow whatever palette is selected. Contrast of the fixed
// colors against the Thread palette is checked by build.mjs, which owns tokens.json.
import { existsSync, mkdirSync, readFileSync, writeFileSync } from "node:fs";
import { dirname } from "node:path";
import { fileURLToPath } from "node:url";

const HERE = dirname(fileURLToPath(import.meta.url));
const ROOT = `${dirname(dirname(HERE))}/`;
const read = (name) => JSON.parse(readFileSync(`${HERE}/${name}`, "utf8"));
const T = read("tokens.json");
const M = read("mobile.json");
const CHECK = process.argv.includes("--check");
const MODES = ["light", "dark", "highContrastLight", "highContrastDark"];
const strip = (group) => Object.fromEntries(Object.entries(group).filter(([key]) => !key.startsWith("$")));
const HEADER = "Generated by design/tokens/build-mobile.mjs from design/tokens/tokens.json and mobile.json. Do not edit by hand.";

// ---- rules ----------------------------------------------------------------------------------------------------
const failures = [];
const roles = Object.keys(T.type.roles);
for (const role of roles) if (!M.type.roles[role]) failures.push(`mobile.json has no type role "${role}" (tokens.json does)`);
for (const role of Object.keys(M.type.roles)) if (!T.type.roles[role]) failures.push(`mobile.json type role "${role}" is not in tokens.json`);
if (M.size.target.ios < 44) failures.push(`iOS tap target ${M.size.target.ios} is under 44pt`);
if (M.size.target.android < 48) failures.push(`Android tap target ${M.size.target.android} is under 48dp`);
for (const os of ["ios", "android"])
  for (const [role, value] of Object.entries(M.type.roles))
    if (value[os] && value[os][0] < M.type.minimumReadable[os]) failures.push(`${os} type role "${role}" (${value[os][0]}) is under the minimum readable size`);
if (failures.length) {
  console.error(`Mobile token rules failed:\n  ${failures.join("\n  ")}`);
  process.exit(1);
}

const fixed = strip(T.fixed);
const space = strip(T.space);
const elevation = strip(T.elevation);
const hex = (value) => value.slice(1).toUpperCase();

// ---- Swift (iOS) ----------------------------------------------------------------------------------------------
const swiftWeight = (w) => ({ 400: ".regular", 500: ".medium", 600: ".semibold", 700: ".bold" })[w];
const swift = `// ${HEADER}
// swiftlint:disable all
import SwiftUI

/// Sizes, type, shape and motion for the Thread design system (iPhone values).
enum WTokens {
    enum Space {
${Object.entries(space).map(([k, v]) => `        static let ${k}: CGFloat = ${v}`).join("\n")}
    }

    enum Radius {
${Object.entries(strip(M.radius.ios)).map(([k, v]) => `        static let ${k}: CGFloat = ${v}`).join("\n")}
    }

    /// One type role at the default text size. \`relativeTo\` is the Dynamic Type style it scales with.
    struct TypeRole: Sendable {
        let size: CGFloat
        let lineHeight: CGFloat
        let weight: Font.Weight
        let relativeTo: Font.TextStyle
    }

    enum TypeScale {
${roles.map((k) => `        static let ${k} = TypeRole(size: ${M.type.roles[k].ios[0]}, lineHeight: ${M.type.roles[k].ios[1]}, weight: ${swiftWeight(T.type.roles[k].weight)}, relativeTo: .${M.type.roles[k].ios[2]})`).join("\n")}
        static let minimumReadable: CGFloat = ${M.type.minimumReadable.ios}
        static let readingMeasure: Int = ${T.type.readingMeasure}
    }

    /// A shadow: vertical offset, blur radius, and opacity of the scrim color.
    struct Shadow: Sendable {
        let y: CGFloat
        let blur: CGFloat
        let opacity: Double
    }

    enum Elevation {
${Object.entries(elevation).map(([k, v]) => `        static let level${k} = Shadow(y: ${v[0]}, blur: ${v[1]}, opacity: ${v[2]})`).join("\n")}
    }

    /// Durations in seconds. With Reduce Motion, components fade and do not move.
    enum Motion {
${Object.entries(M.motion.duration.ios).map(([k, v]) => `        static let ${k}: Double = ${v / 1000}`).join("\n")}
    }

    enum Size {
        static let target: CGFloat = ${M.size.target.ios}
        static let spine: CGFloat = ${M.size.spine}
        static let contentMax: CGFloat = ${M.size.contentMax}
    }
}

/// A color a theme cannot change, in its four variants (0xRRGGBB).
struct WFixedColor: Sendable {
    let light: UInt32
    let dark: UInt32
    let highContrastLight: UInt32
    let highContrastDark: UInt32
}

enum WFixed {
${Object.entries(fixed).map(([k, t]) => `    static let ${k} = WFixedColor(light: 0x${hex(t.$value[0])}, dark: 0x${hex(t.$value[1])}, highContrastLight: 0x${hex(t.$value[2])}, highContrastDark: 0x${hex(t.$value[3])})`).join("\n")}
    static let all: [String: WFixedColor] = [${Object.keys(fixed).map((k) => `"${k}": ${k}`).join(", ")}]
}

/// The Thread palette on the 15 skinnable tokens, keyed by the names themes/*.json uses. For the debug
/// gallery and tests; the apps read the selected palette through the theme loader.
enum WThreadPalette {
${MODES.map((m) => `    static let ${m}: [String: UInt32] = [${Object.entries(T.palette[m]).map(([k, v]) => `"${k}": 0x${hex(v)}`).join(", ")}]`).join("\n")}
}
`;

// ---- Kotlin (Android) -----------------------------------------------------------------------------------------
const kotlin = `// ${HEADER}
@file:Suppress("MagicNumber", "unused")

package com.mpointer.whimbrel.mobile.design

import androidx.compose.ui.text.font.FontWeight
import androidx.compose.ui.unit.Dp
import androidx.compose.ui.unit.TextUnit
import androidx.compose.ui.unit.dp
import androidx.compose.ui.unit.sp

/** Sizes, type, shape and motion for the Thread design system (Android values). */
object WTokens {
    object Space {
${Object.entries(space).map(([k, v]) => `        val ${k}: Dp = ${v}.dp`).join("\n")}
    }

    object Radius {
${Object.entries(strip(M.radius.android)).map(([k, v]) => `        val ${k}: Dp = ${v}.dp`).join("\n")}
    }

    /** One type role. Sizes are sp, so they follow the system font scale. */
    data class TypeRole(val size: TextUnit, val lineHeight: TextUnit, val weight: FontWeight)

    object TypeScale {
${roles.map((k) => `        val ${k} = TypeRole(${M.type.roles[k].android[0]}.sp, ${M.type.roles[k].android[1]}.sp, FontWeight(${T.type.roles[k].weight}))`).join("\n")}
        val minimumReadable: TextUnit = ${M.type.minimumReadable.android}.sp
        const val readingMeasure: Int = ${T.type.readingMeasure}
    }

    /** A shadow: vertical offset, blur radius, and opacity of the scrim color. */
    data class Shadow(val y: Dp, val blur: Dp, val opacity: Float)

    object Elevation {
${Object.entries(elevation).map(([k, v]) => `        val level${k} = Shadow(${v[0]}.dp, ${v[1]}.dp, ${v[2]}f)`).join("\n")}
    }

    /** Durations in milliseconds. With animations off, components fade and do not move. */
    object Motion {
${Object.entries(M.motion.duration.android).map(([k, v]) => `        const val ${k}: Int = ${v}`).join("\n")}
    }

    object Size {
        val target: Dp = ${M.size.target.android}.dp
        val spine: Dp = ${M.size.spine}.dp
        val contentMax: Dp = ${M.size.contentMax}.dp
    }
}

/** A color a theme cannot change, in its four variants (0xRRGGBB). */
data class WFixedColor(val light: Int, val dark: Int, val highContrastLight: Int, val highContrastDark: Int)

object WFixed {
${Object.entries(fixed).map(([k, t]) => `    val ${k} = WFixedColor(0x${hex(t.$value[0])}, 0x${hex(t.$value[1])}, 0x${hex(t.$value[2])}, 0x${hex(t.$value[3])})`).join("\n")}
    val all: Map<String, WFixedColor> = mapOf(${Object.keys(fixed).map((k) => `"${k}" to ${k}`).join(", ")})
}

/**
 * The Thread palette on the 15 skinnable tokens, keyed by the names the theme files use. For the debug
 * gallery and tests; the app reads the selected palette through the theme loader.
 */
object WThreadPalette {
${MODES.map((m) => `    val ${m}: Map<String, Int> = mapOf(${Object.entries(T.palette[m]).map(([k, v]) => `"${k}" to 0x${hex(v)}`).join(", ")})`).join("\n")}
}
`;

const outputs = {
  "apps/mobile/ios/Whimbrel/DesignSystem/Tokens.generated.swift": swift,
  "apps/mobile/android/app/src/main/java/com/mpointer/whimbrel/mobile/design/Tokens.generated.kt": kotlin,
};

let stale = 0;
for (const [path, text] of Object.entries(outputs)) {
  const full = `${ROOT}${path}`;
  const current = existsSync(full) ? readFileSync(full, "utf8").replace(/\r\n/g, "\n") : null;
  if (current === text) continue;
  stale++;
  if (CHECK) console.error(`out of date: ${path}`);
  else {
    mkdirSync(dirname(full), { recursive: true });
    writeFileSync(full, text);
    console.log(`wrote ${path}`);
  }
}
if (CHECK && stale) {
  console.error("Run: node design/tokens/build-mobile.mjs");
  process.exit(1);
}
